arguments.command:
cd /workspace && python3 -I - <<'EOF'
import json, re
ANSWER_RE = re.compile(r"<answer>(.*?)</answer>", re.DOTALL)
from fractions import Fraction
import ast

def parse_gt(s):
    return json.loads(s)

for f in ['results/grpo_countdown/val_generations/0.jsonl','results/grpo_countdown/val_generations/15.jsonl','results/grpo_countdown/val_generations/30.jsonl','results/grpo_countdown/val_generations/45.jsonl']:
    rows=[json.loads(l) for l in open(f)]
    n=len(rows)
    n_ans=sum(1 for r in rows if ANSWER_RE.search(r['output']))
    n_correct=sum(1 for r in rows if r['acc']==1.0)
    # categorize failures at last answer tag
    no_tag=0; malformed=0; wrong_nums=0; wrong_val=0; correct=0
    for r in rows:
        m=ANSWER_RE.findall(r['output'])
        gt=parse_gt(r['gts'])
        if not m:
            no_tag+=1; continue
        expr=m[-1].strip().replace('\\times','*').replace('\\div','/').replace('×','*').replace('÷','/')
        if '=' in expr: expr=expr.split('=')[0].strip()
        ok_chars = bool(re.fullmatch(r"[0-9+\-*/()\s]+", expr)) and expr and len(expr)<=256
        if not ok_chars:
            malformed+=1; continue
        try:
            tree=ast.parse(expr, mode='eval')
            used=[]
            def ev(node):
                if isinstance(node, ast.Expression): return ev(node.body)
                if isinstance(node, ast.Constant) and type(node.value) is int:
                    used.append(node.value); return Fraction(node.value)
                if isinstance(node, ast.BinOp):
                    l=ev(node.left); r=ev(node.right)
                    if isinstance(node.op, ast.Add): return l+r
                    if isinstance(node.op, ast.Sub): return l-r
                    if isinstance(node.op, ast.Mult): return l*r
                    if isinstance(node.op, ast.Div): return Fraction(l,r)
                raise ValueError()
            val=ev(tree)
        except Exception:
            malformed+=1; continue
        if sorted(used)!=sorted(gt['numbers']):
            wrong_nums+=1; continue
        if val==Fraction(gt['target']): correct+=1
        else: wrong_val+=1
    print(f, "n=",n, "acc=", round(n_correct/n,4), "no_tag=",no_tag, "malformed=",malformed, "wrong_nums=",wrong_nums, "wrong_val=",wrong_val, "correct=",correct)
EOF

